<?php
declare(strict_types=1);namespace App\Interfaces\Http\Controllers\Api\V1\Payments;
use App\Application\Payments\FinancialCaseService;use App\Domain\Tenancy\TenantContext;use App\Models\{Chargeback,PaymentIntentRecord,Refund};use Illuminate\Http\{JsonResponse,Request};
final class FinancialControlController{private function payment(string$id):PaymentIntentRecord{return PaymentIntentRecord::where('tenant_id',app(TenantContext::class)->id())->findOrFail($id);}public function openChargeback(Request$r,string$payment,FinancialCaseService$s):JsonResponse{$d=$r->validate(['provider_case_reference'=>'required|string|max:160','amount_minor'=>'required|integer|min:1','reason_code'=>'required|string|max:64','response_due_at'=>'nullable|date','evidence'=>'sometimes|array']);return response()->json(['data'=>$s->openChargeback($this->payment($payment),$d)],201);}public function resolveChargeback(Request$r,string$chargeback,FinancialCaseService$s):JsonResponse{$d=$r->validate(['decision'=>'required|in:WON,LOST,CLOSED','reason_code'=>'required|string|max:64','notes'=>'required|string|min:20|max:4000']);$c=Chargeback::where('tenant_id',app(TenantContext::class)->id())->findOrFail($chargeback);return response()->json(['data'=>$s->resolveChargeback($c,$d,$r->user())]);}}
